const input = $json;
const validation = $("Validate URL — NGP-005").first().json;

// Normalise header names to lowercase
const headers = {};
for (const [k, v] of Object.entries(input.headers ?? {})) {
  headers[String(k).toLowerCase()] = v;
}
const reachable = Object.keys(headers).length > 0;

const requiredHeaders = [
  {
    name: "Content-Security-Policy",
    key: "content-security-policy",
    fix: "Add a Content-Security-Policy that restricts scripts, styles, images, and other resource sources."
  },
  {
    name: "Strict-Transport-Security",
    key: "strict-transport-security",
    fix: "Serve the site over HTTPS and configure Strict-Transport-Security with an appropriate max-age."
  },
  {
    name: "X-Frame-Options",
    key: "x-frame-options",
    fix: "Set X-Frame-Options to DENY or SAMEORIGIN to reduce clickjacking risk."
  },
  {
    name: "X-Content-Type-Options",
    key: "x-content-type-options",
    fix: "Set X-Content-Type-Options: nosniff to prevent MIME-type sniffing."
  },
  {
    name: "Referrer-Policy",
    key: "referrer-policy",
    fix: "Set Referrer-Policy to strict-origin-when-cross-origin or a stricter suitable policy."
  }
];

const headerResults = requiredHeaders.map(header => {
  const value = headers[header.key];
  const present = value !== undefined && value !== null && String(value).trim() !== "";
  return {
    header: header.name,
    present,
    value: present ? String(value).slice(0, 200) : "Missing",
    fix: present ? "" : header.fix
  };
});

const score = headerResults.filter(item => item.present).length;

return {
  json: {
    chatId: validation.chatId,
    url: validation.url,
    note: validation.note ?? "",
    auditTag: "NGP-005",
    statusCode: input.statusCode ?? null,
    reachable,
    headerResults,
    score,
    total: requiredHeaders.length,
    verdict: score === 5 ? "PASS" : "FAIL",
    summary: `${score}/5 security headers present.`
  }
};

const input = $json;

const message = String(input.message?.text ?? input.text ?? "").trim();
const chatId = input.message?.chat?.id ?? input.chat?.id ?? input.chatId;

// ---- Config ----
const DEFAULT_URL = "http://demo.testfire.net";   // approved practice target
const ALLOW_ANY_PUBLIC_URL = true;                // false = only allowedOrigins below
const allowedOrigins = ["http://demo.testfire.net"];

// ---- Extract a URL from the Telegram message ----
const md = message.match(/\]\((https?:\/\/[^)\s]+)\)/);          // [text](url)
const plain = message.match(/https?:\/\/[^\s<>()\[\]]+/i);       // plain http(s) URL
let candidate = md ? md[1] : plain ? plain[0] : "";

if (!candidate && /^[a-z0-9-]+(\.[a-z0-9-]+)+(\/\S*)?$/i.test(message)) {
  candidate = "https://" + message;                              // bare domain
}

candidate = candidate.replace(/[.,;!?]+$/, "");
const hostMatch = candidate.match(/^https?:\/\/([^\/:?#]+)/i);
const host = hostMatch ? hostMatch[1].toLowerCase() : "";

// ---- Block internal / private targets (SSRF protection) ----
const isPrivateHost = (h) =>
  h === "localhost" ||
  h.endsWith(".local") ||
  h.endsWith(".internal") ||
  /^127\./.test(h) ||
  /^10\./.test(h) ||
  /^0\./.test(h) ||
  /^192\.168\./.test(h) ||
  /^169\.254\./.test(h) ||
  /^172\.(1[6-9]|2\d|3[01])\./.test(h) ||
  h.includes(":") ||
  !h.includes(".");

let url = DEFAULT_URL;
let note = "";

if (!candidate) {
  note = "No URL found in your message, so the default practice URL was audited.";
} else if (isPrivateHost(host)) {
  note = "That target is internal/private and was blocked, so the default practice URL was audited.";
} else if (!ALLOW_ANY_PUBLIC_URL && !allowedOrigins.some(o => candidate.toLowerCase().startsWith(o))) {
  note = "That URL is not on the approved list, so the default practice URL was audited.";
} else {
  url = candidate;
}

return {
  json: {
    chatId,
    receivedText: message,
    url,
    allowed: true,
    note,
    reason: note || "Requested URL accepted.",
    tag: "NGP-005"
  }
};

const audit = $("Audit Security Headers — NGP-005").first().json;
const ai = $json;

const chatId = audit.chatId;
const url = String(audit.url ?? "");

const score = audit.score ?? 0;
const total = audit.total ?? 5;
const verdict = audit.verdict ?? "FAIL";

// 0-1 = red, 2-3 = orange, 4-5 = green
const severity =
  score <= 1 ? "red" :
  score <= 3 ? "orange" :
  "green";
const icon = { red: "🔴", orange: "🟠", green: "🟢" }[severity];

const headerResults = audit.headerResults ?? [];

const headerLines = headerResults.map(h =>
  `${h.present ? "✅" : "❌"} ${h.header}: ${h.present ? "Present" : "Missing"}`
).join("\n");

let aiExplanation = String(
  ai.output ??
  ai.text ??
  "AI explanation unavailable. Review the missing-header fixes from the audit results."
).trim();
if (aiExplanation.length > 1200) aiExplanation = aiExplanation.slice(0, 1197) + "...";

const extra = [
  audit.reachable === false ? "⚠️ Target could not be reached - results may be inaccurate." : "",
  audit.note ? `ℹ️ ${audit.note}` : ""
].filter(Boolean).join("\n");

const message = `🛡️ NGP-005 Security Header Audit

URL: ${url}

Score: ${score}/${total}
Verdict: ${String(verdict).toUpperCase()}
Severity: ${icon} ${severity.toUpperCase()}
${extra ? "\n" + extra + "\n" : ""}
${headerLines}

AI Analysis:
${aiExplanation}

Tag: NGP-005`;

return {
  json: {
    chatId,
    url,
    severity,
    score,
    total,
    verdict,
    headerResults,
    aiExplanation,
    message,
    tag: "NGP-005"
  }
};

const input = $json;

const allowedSeverities = ["red", "orange", "green"];
const allowedVerdicts = ["PASS", "FAIL"];
const allowedHeaders = [
  "Content-Security-Policy",
  "Strict-Transport-Security",
  "X-Frame-Options",
  "X-Content-Type-Options",
  "Referrer-Policy"
];

const message = String(input.message ?? "");

const valid =
  Number.isInteger(input.score) &&
  input.score >= 0 &&
  input.score <= 5 &&
  allowedSeverities.includes(input.severity) &&
  allowedVerdicts.includes(input.verdict) &&
  input.tag === "NGP-005" &&
  Number.isFinite(Number(input.chatId)) &&
  message.length > 0 &&
  message.length <= 3500 &&
  allowedHeaders.every(header => message.includes(header));

return {
  json: {
    ...input,
    valid,
    validationReason: valid
      ? "Output passed validation"
      : "Output failed validation",
    validationAttempt: 1
  }
};

const i = $json;

const lines = (i.headerResults ?? []).map(h =>
  `${h.present ? "✅" : "❌"} ${h.header}: ${h.present ? "Present" : "Missing"}`
).join("\n");

const message = `🛡️ NGP-005 Security Header Audit

URL: ${i.url}

Score: ${i.score}/${i.total}
Verdict: ${String(i.verdict).toUpperCase()}
Severity: ${String(i.severity).toUpperCase()}

${lines}

⚠️ The AI analysis was skipped because the report failed validation.

Tag: NGP-005`;

return { json: { ...i, message } };
